/** El cuerpo del runtime, que suelta la admisión cuando se agota o el cliente lo cancela. */
function releasingBody(body: ReadableStream<Uint8Array> | null, release: () => void): ReadableStream<Uint8Array> {
  if (body === null) {
    release()
    return new ReadableStream({ start: controller => controller.close() })
  }
  const reader = body.getReader()
  let headersFlushed = false
  return new ReadableStream<Uint8Array>({
    async pull(controller) {
      if (!headersFlushed) {
        headersFlushed = true
        await yieldToServer()
      }
      try {
        const chunk = await reader.read()
        if (chunk.done) {
          controller.close()
          release()
          return
        }
        controller.enqueue(chunk.value)
      } catch (error) {
        release()
        controller.error(error)
      }
    },
    async cancel(reason) {
      release()
      await reader.cancel(reason)
    },
  }, { highWaterMark: 0 })
}

/**
 * Bun.serve agota un cuerpo que se lee sin pausa ANTES de escribir la
 * respuesta al socket (medido: el stream cerraba antes de que el cliente
 * viera las cabeceras, y `finish` se adelantaba a la entrega). Dejar el
 * primer `pull` pendiente una macrotarea hace que el servidor envíe las
 * cabeceras primero, y el cierre del stream sigue a la entrega real.
 */
function yieldToServer(): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, 0))
}

EOF
